<script setup lang="ts">
import { Pencil, X } from 'lucide-vue-next'
const api=useApi(); const { data: products, refresh }=await useAsyncData('admin-products',()=>api.request<any[]>('/admin/products').catch(()=>[]))
const active=ref<any>(null); const saving=ref(false)
function edit(p:any){active.value={...p}}
async function save(){saving.value=true;try{await api.request(`/admin/products/${active.value._id}`,{method:'POST',body:{priceUsd:Number(active.value.priceUsd),stock:Number(active.value.stock),active:active.value.active,leadTime:active.value.leadTime}});active.value=null;await refresh()}finally{saving.value=false}}
</script>
<template><div><div class="mb-5 flex items-end justify-between"><div><p class="label-mono text-signal-deep">Supply</p><h1 class="mt-1 font-display text-[32px] tracking-[-.04em]">Catalog.</h1><p class="mt-1 text-[11.5px] text-ink/45">Pricing, inventory and publication across the marketplace.</p></div><span class="font-mono text-[9px] uppercase tracking-[.08em] text-ink/35">{{ products?.length }} SKUs</span></div><div class="a-card overflow-hidden"><table class="w-full text-left text-[11px]"><thead class="border-b border-ink/10 bg-paper"><tr class="font-mono text-[7.5px] uppercase tracking-[.08em] text-ink/35"><th class="px-4 py-2.5">Product</th><th class="px-4 py-2.5">Category</th><th class="px-4 py-2.5">Price</th><th class="px-4 py-2.5">Stock</th><th class="px-4 py-2.5">Vendor</th><th class="px-4 py-2.5">Active</th><th class="px-4 py-2.5"></th></tr></thead><tbody><tr v-for="p in products" :key="p._id" class="border-t border-ink/10"><td class="px-4 py-3"><p class="font-medium">{{ p.name }}</p><p class="font-mono text-[7.5px] text-ink/30">{{ p.sku }}</p></td><td class="px-4 py-3">{{ p.category }}</td><td class="px-4 py-3">{{ money(p.priceUsd) }}</td><td class="px-4 py-3">{{ p.stock }}</td><td class="px-4 py-3 text-ink/45">{{ p.vendor }}</td><td class="px-4 py-3"><StatusPill :status="p.active ? 'active' : 'draft'"/></td><td class="px-4 py-3"><button class="text-ink/35 hover:text-ink" @click="edit(p)"><Pencil :size="13"/></button></td></tr></tbody></table></div>
  <div v-if="active" class="fixed inset-0 z-[70] flex items-center justify-center bg-ink/40 p-4" @click.self="active=null"><div class="w-full max-w-sm rounded-xl bg-bone p-5"><div class="flex items-start justify-between"><div><p class="label-mono text-signal-deep">Edit listing</p><h2 class="mt-1 font-display text-[22px]">{{ active.name }}</h2></div><button @click="active=null"><X :size="17"/></button></div><div class="mt-4 space-y-3"><div><label class="a-label">Price (USD)</label><input v-model.number="active.priceUsd" type="number" class="a-input"></div><div><label class="a-label">Stock</label><input v-model.number="active.stock" type="number" class="a-input"></div><div><label class="a-label">Lead time</label><input v-model="active.leadTime" class="a-input"></div><label class="flex items-center gap-2 text-[11px]"><input v-model="active.active" type="checkbox"> Published in marketplace</label></div><div class="mt-5 flex justify-end gap-2"><button class="btn btn-outline" @click="active=null">Cancel</button><button class="btn btn-dark" :disabled="saving" @click="save">{{ saving ? 'Saving…' : 'Save changes' }}</button></div></div></div>
</div></template>
